def upload(store, tenant, request_key, digest, asset_id):
    key = (tenant, request_key)
    old = store.get(key)
    if old:
        if old['digest'] != digest: raise ValueError('KEY_REUSE')
        return old['asset_id']
    store[key] = {'digest': digest, 'asset_id': asset_id}
    return asset_id

